-- Creates the table and loads all 113 survey responses.
-- How to run: pgAdmin > Query Tool > open this file > press F5.
SET client_encoding = 'UTF8';

DROP TABLE IF EXISTS respondents;
CREATE TABLE respondents (
    resp_id            INT PRIMARY KEY,
    submitted_ts       TIMESTAMP,
    age_group          TEXT,
    gender             TEXT,
    residence          TEXT,
    two_city           SMALLINT,
    orders             TEXT,
    products           TEXT,
    platforms          TEXT,
    rk_price           SMALLINT,
    rk_speed           SMALLINT,
    rk_quality         SMALLINT,
    rk_packaging       SMALLINT,
    rk_returns         SMALLINT,
    opted_minimal      TEXT,
    excess_pack        TEXT,
    materials          TEXT,
    cos_effort         TEXT,
    campaigns          TEXT,
    disposal           TEXT,
    reduce_waste       TEXT,
    contacted_co       TEXT,
    pay_premium        TEXT,
    accept_slower      TEXT,
    incentives         TEXT,
    legal_req          TEXT,
    policy_pref        TEXT,
    return_prog        TEXT,
    challenge          TEXT,
    excess_n           SMALLINT,
    opted_n            SMALLINT,
    effort_n           SMALLINT,
    campaign_n         SMALLINT,
    premium_n          SMALLINT,
    pay_yes            SMALLINT,
    slower_n           SMALLINT,
    legal_n            SMALLINT,
    return_n           SMALLINT,
    prod_fashion       SMALLINT,
    prod_grocery       SMALLINT,
    prod_health        SMALLINT,
    prod_electronics   SMALLINT,
    prod_home          SMALLINT,
    prod_other         SMALLINT,
    plat_amazon        SMALLINT,
    plat_flipkart      SMALLINT,
    plat_myntra        SMALLINT,
    plat_blinkit       SMALLINT,
    plat_zepto         SMALLINT,
    plat_bigbask       SMALLINT,
    plat_nykaa         SMALLINT,
    plat_meesho        SMALLINT,
    plat_ajio          SMALLINT,
    plat_food          SMALLINT,
    plat_other         SMALLINT,
    mat_plastic        SMALLINT,
    mat_cardboard      SMALLINT,
    mat_paper          SMALLINT,
    mat_biodeg         SMALLINT,
    inc_discount       SMALLINT,
    inc_label          SMALLINT,
    inc_govreg         SMALLINT,
    inc_campaign       SMALLINT,
    inc_none           SMALLINT,
    pol_plasticlimit   SMALLINT,
    pol_reuse          SMALLINT,
    pol_taxbreak       SMALLINT,
    pol_community      SMALLINT,
    pol_activism       SMALLINT
);


SELECT COUNT(*) AS rows_loaded FROM respondents;
